Object.assign(SNIP,{});PRESET_NOTES["l40"]={"Ví dụ: Thối tiền bằng ít tờ nhất": "289 = 200 + 50 + 20 + 10 + 5 + 2 + 2: 7 tờ. Với hệ mệnh giá này, tham lam luôn cho số tờ ít nhất.", "Ví dụ: Phản ví dụ với hệ tiền {1, 3, 4}": "Tham lam lấy 4 rồi 1, 1: 3 đồng. Tối ưu là 3 + 3: 2 đồng. Một phản ví dụ là đủ để bác bỏ một thuật toán tham lam.", "Ví dụ: Mua được nhiều món nhất": "Muốn nhiều món nhất thì mua món rẻ nhất trước: 10 + 20 + 30 + 40 = 100, được 4 món. Thay một món đã chọn bằng một món chưa chọn (đắt hơn hoặc bằng) không bao giờ giúp mua thêm.", "Ví dụ: Nhảy xa ít bước nhất": "bien là ô xa nhất tới được bằng buoc bước. Đi qua các ô trong tầm đó, ghi nhận xa nhất có thể với thêm một bước. Ra khỏi tầm thì bắt buộc nhảy thêm. 0 → 1 → 4 → 7: 3 bước, O(n).", "Lỗi: chọn sai tiêu chí tham lam": "Mua đắt trước: 90 rồi chỉ còn 10 mua được món 10: 2 món, trong khi tối ưu là 4. Cùng là tham lam nhưng tiêu chí sai thì kết quả sai."};EX_HINTS["l40"]=[["Sắp xếp giá tăng dần, mua lần lượt cho tới khi không đủ tiền.", "Không cần xét tiếp sau món đầu tiên không mua được: các món sau còn đắt hơn.", "Tìm món rẻ nhất bằng cách duyệt lại cả mảng mỗi lần tốn O(n²)."], ["Em dễ tính nhất (g nhỏ nhất) nên nhận chiếc bánh nhỏ nhất còn làm em vui: dùng bánh to hơn là phí.", "Sắp xếp cả hai mảng, duyệt bánh từ nhỏ đến lớn với một con trỏ vào em dễ tính nhất chưa có bánh.", "Bánh nhỏ hơn g của em đó thì cũng nhỏ hơn g của mọi em còn lại: bỏ qua."], ["Chia các ô thành từng “tầng”: tầng k là các ô tới được bằng đúng k bước mà không ít hơn.", "Duyệt i từ trái sang: xa = max(xa, i + a[i]). Khi i chạm biên của tầng hiện tại, buộc phải nhảy thêm: buoc++, biên mới là xa.", "Chỉ duyệt tới n − 2: đứng ở ô n − 1 rồi thì không cần nhảy. n = 1 thì đáp án 0."]];
/* ===================== BÀI 40 · Ý tưởng tham lam và khi nào nó đúng ===================== */
/* Bài 40 · Ý tưởng tham lam và khi nào nó đúng
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR40=[{label:"Ví dụ: Thối tiền bằng ít tờ nhất",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int menhGia[9] = {500, 200, 100, 50, 20, 10, 5, 2, 1};   // nghìn đồng, giảm dần\n    int con = 289, soTo = 0;\n    for (int i = 0; i < 9; i++) {\n        while (con >= menhGia[i]) {    // tờ lớn nhất còn vừa\n            con -= menhGia[i];\n            soTo++;\n            cout << menhGia[i] << \" \";\n        }\n    }\n    cout << \"\\n\" << soTo << \" to\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"menhGia",ptr:["i"]},{type:"vars",names:["con","soTo"]}],py:{code:"menh_gia = [500, 200, 100, 50, 20, 10, 5, 2, 1]   # nghìn đồng, giảm dần\ncon, so_to = 289, 0\nda_dua = []\nfor i in range(len(menh_gia)):\n    while con >= menh_gia[i]:          # tờ lớn nhất còn vừa\n        con -= menh_gia[i]\n        so_to += 1\n        da_dua.append(menh_gia[i])\nprint(*da_dua)\nprint(so_to, \"to\")",viz:[{type:"cells",of:"menh_gia",ptr:["i"]},{type:"vars",names:["con","so_to"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] menhGia = { 500, 200, 100, 50, 20, 10, 5, 2, 1 };   // nghìn đồng, giảm dần\n        int con = 289, soTo = 0;\n        for (int i = 0; i < menhGia.Length; i++)\n        {\n            while (con >= menhGia[i])          // tờ lớn nhất còn vừa\n            {\n                con -= menhGia[i];\n                soTo++;\n                Console.Write(menhGia[i] + \" \");\n            }\n        }\n        Console.WriteLine();\n        Console.WriteLine(soTo + \" to\");\n    }\n}"}},{label:"Ví dụ: Phản ví dụ với hệ tiền {1, 3, 4}",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int c[3] = {4, 3, 1};\n    int x = 6;\n    int con = x, thamLam = 0;\n    for (int i = 0; i < 3; i++)\n        while (con >= c[i]) { con -= c[i]; thamLam++; }\n\n    int best[7];                       // best[s]: số đồng ít nhất để đổi s (vét cạn từ nhỏ đến lớn)\n    best[0] = 0;\n    for (int s = 1; s <= x; s++) {\n        best[s] = 1000;\n        for (int i = 0; i < 3; i++)\n            if (c[i] <= s) best[s] = min(best[s], best[s - c[i]] + 1);\n    }\n    cout << \"tham lam: \" << thamLam << \", toi uu: \" << best[x] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"best",ptr:["s"]},{type:"vars",names:["con","thamLam"]}],py:{code:"c = [4, 3, 1]\nx = 6\ncon, tham_lam = x, 0\nfor d in c:\n    while con >= d:\n        con -= d\n        tham_lam += 1\n\nbest = [0] * (x + 1)                   # best[s]: số đồng ít nhất để đổi s (vét cạn từ nhỏ đến lớn)\nfor s in range(1, x + 1):\n    best[s] = min(best[s - d] + 1 for d in c if d <= s)\nprint(\"tham lam:\", tham_lam, \", toi uu:\", best[x])",viz:[{type:"cells",of:"best",ptr:["s"]},{type:"vars",names:["con","tham_lam"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] c = { 4, 3, 1 };\n        int x = 6;\n        int con = x, thamLam = 0;\n        foreach (int d in c)\n            while (con >= d) { con -= d; thamLam++; }\n\n        int[] best = new int[x + 1];           // best[s]: số đồng ít nhất để đổi s (vét cạn từ nhỏ đến lớn)\n        for (int s = 1; s <= x; s++)\n        {\n            best[s] = 1000;\n            foreach (int d in c)\n                if (d <= s) best[s] = Math.Min(best[s], best[s - d] + 1);\n        }\n        Console.WriteLine(\"tham lam: \" + thamLam + \", toi uu: \" + best[x]);\n    }\n}"}},{label:"Ví dụ: Mua được nhiều món nhất",input:"",code:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int gia[7] = {40, 10, 70, 20, 50, 30, 90};\n    int tien = 100, soMon = 0;\n    sort(gia, gia + 7);                // rẻ nhất trước\n    for (int i = 0; i < 7; i++) {\n        if (gia[i] > tien) break;      // món rẻ nhất còn lại cũng không đủ tiền\n        tien -= gia[i];\n        soMon++;\n    }\n    cout << soMon << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"gia",ptr:["i"]},{type:"vars",names:["tien","soMon"]}],py:{code:"gia = [40, 10, 70, 20, 50, 30, 90]\ntien, so_mon = 100, 0\ngia.sort()                             # rẻ nhất trước\nfor i in range(len(gia)):\n    if gia[i] > tien:                  # món rẻ nhất còn lại cũng không đủ tiền\n        break\n    tien -= gia[i]\n    so_mon += 1\nprint(so_mon)",viz:[{type:"bars",of:"gia",ptr:["i"]},{type:"vars",names:["tien","so_mon"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] gia = { 40, 10, 70, 20, 50, 30, 90 };\n        int tien = 100, soMon = 0;\n        Array.Sort(gia);                       // rẻ nhất trước\n        for (int i = 0; i < gia.Length; i++)\n        {\n            if (gia[i] > tien) break;          // món rẻ nhất còn lại cũng không đủ tiền\n            tien -= gia[i];\n            soMon++;\n        }\n        Console.WriteLine(soMon);\n    }\n}"}},{label:"Ví dụ: Nhảy xa ít bước nhất",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[8] = {2, 3, 1, 1, 4, 2, 1, 1};   // từ ô i nhảy được tới ô i+1 … i+a[i]\n    int n = 8, buoc = 0, bien = 0, xa = 0;\n    for (int i = 0; i < n - 1; i++) {\n        xa = max(xa, i + a[i]);        // ô xa nhất tới được bằng buoc + 1 bước\n        if (i == bien) {               // đã dùng hết tầm của buoc bước\n            buoc++;\n            bien = xa;\n        }\n    }\n    cout << buoc << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i","bien","xa"]}],py:{code:"a = [2, 3, 1, 1, 4, 2, 1, 1]           # từ ô i nhảy được tới ô i+1 … i+a[i]\nn = len(a)\nbuoc = bien = xa = 0\nfor i in range(n - 1):\n    xa = max(xa, i + a[i])             # ô xa nhất tới được bằng buoc + 1 bước\n    if i == bien:                      # đã dùng hết tầm của buoc bước\n        buoc += 1\n        bien = xa\nprint(buoc)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 2, 3, 1, 1, 4, 2, 1, 1 };  // từ ô i nhảy được tới ô i+1 … i+a[i]\n        int n = a.Length, buoc = 0, bien = 0, xa = 0;\n        for (int i = 0; i < n - 1; i++)\n        {\n            xa = Math.Max(xa, i + a[i]);       // ô xa nhất tới được bằng buoc + 1 bước\n            if (i == bien)                     // đã dùng hết tầm của buoc bước\n            {\n                buoc++;\n                bien = xa;\n            }\n        }\n        Console.WriteLine(buoc);\n    }\n}"}},{label:"Lỗi: chọn sai tiêu chí tham lam",input:"",code:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int gia[7] = {40, 10, 70, 20, 50, 30, 90};\n    int tien = 100, soMon = 0;\n    sort(gia, gia + 7);\n    for (int i = 6; i >= 0; i--) {     // SAI: mua món đắt nhất trước\n        if (gia[i] <= tien) {\n            tien -= gia[i];\n            soMon++;\n        }\n    }\n    cout << soMon << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"gia",ptr:["i"]},{type:"vars",names:["tien","soMon"]}],py:{code:"gia = [40, 10, 70, 20, 50, 30, 90]\ntien, so_mon = 100, 0\ngia.sort()\nfor i in range(len(gia) - 1, -1, -1):  # SAI: mua món đắt nhất trước\n    if gia[i] <= tien:\n        tien -= gia[i]\n        so_mon += 1\nprint(so_mon)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] gia = { 40, 10, 70, 20, 50, 30, 90 };\n        int tien = 100, soMon = 0;\n        Array.Sort(gia);\n        for (int i = gia.Length - 1; i >= 0; i--)   // SAI: mua món đắt nhất trước\n        {\n            if (gia[i] <= tien)\n            {\n                tien -= gia[i];\n                soMon++;\n            }\n        }\n        Console.WriteLine(soMon);\n    }\n}"}}];
