makeEx2(document.getElementById("ex-l40"),sim40,[{t:"Mua được nhiều món nhất",d:"Có n món hàng với giá a₁ … aₙ và số tiền B. Mỗi món mua tối đa một lần. Đầu vào: n và B (1 ≤ n ≤ 10^5, 0 ≤ B ≤ 10^14); dòng sau là n giá (1 ≤ aᵢ ≤ 10^9). Đầu ra: số món nhiều nhất mua được.",tests:[{in:"7 100\n40 10 70 20 50 30 90",out:"4"},{in:"1 4\n5",out:"0"},{in:"1 5\n5",out:"1"},{in:"3 10\n1 1 1",out:"3"},{in:"4 3000000000\n1000000000 1000000000 1000000000 1000000000",out:"3"},{in:"50 500\n1 38 75 12 49 86 23 60 97 34 71 8 45 82 19 56 93 30 67 4 41 78 15 52 89 26 63 100 37 74 11 48 85 22 59 96 33 70 7 44 81 18 55 92 29 66 3 40 77 14",out:"22"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    long long B;\n    cin >> n >> B;\n    vector<long long> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int soMon = 0;\n    // mua món rẻ nhất trước\n    cout << soMon << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" "+(n*300)+"\n"+Array.from({length:n},(_,i)=>(i*7919)%1000+1).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Mỗi lần duyệt cả mảng tìm món rẻ nhất là O(n²). Sắp xếp một lần rồi duyệt là O(n log n)."},py:{start:"n, B = map(int, input().split())\na = list(map(int, input().split()))\nso_mon = 0\n# mua món rẻ nhất trước\nprint(so_mon)",hints:["Sắp xếp giá tăng dần, mua lần lượt cho tới khi không đủ tiền.","Không cần xét tiếp sau món đầu tiên không mua được: các món sau còn đắt hơn.","Gọi min() rồi remove() mỗi lần là O(n²)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] nb = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        long B = nb[1];\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        int soMon = 0;\n        // mua món rẻ nhất trước\n        Console.WriteLine(soMon);\n    }\n}",hints:["Sắp xếp giá tăng dần (Array.Sort), mua lần lượt cho tới khi không đủ tiền.","Không cần xét tiếp sau món đầu tiên không mua được: các món sau còn đắt hơn.","B tới 10^14: dùng long."]}},{t:"Chia bánh",d:"Có n em bé, em thứ i chỉ vui khi nhận chiếc bánh cỡ ít nhất gᵢ; có m chiếc bánh cỡ s₁ … sₘ. Mỗi em nhận tối đa một bánh, mỗi bánh cho tối đa một em. Đầu vào: n và m (1 ≤ n, m ≤ 10^5); dòng 2 là các gᵢ; dòng 3 là các sⱼ (1 ≤ gᵢ, sⱼ ≤ 10^9). Đầu ra: số em vui nhiều nhất.",tests:[{in:"3 2\n1 2 3\n1 1",out:"1"},{in:"2 3\n1 2\n1 2 3",out:"2"},{in:"1 1\n5\n4",out:"0"},{in:"3 2\n3 3 3\n3 3",out:"2"},{in:"4 4\n10 1 8 2\n9 3 1 7",out:"3"},{in:"40 30\n1 38 25 12 49 36 23 10 47 34 21 8 45 32 19 6 43 30 17 4 41 28 15 2 39 26 13 50 37 24 11 48 35 22 9 46 33 20 7 44\n1 4 7 10 13 16 19 22 25 28 31 34 37 40 43 46 49 2 5 8 11 14 17 20 23 26 29 32 35 38",out:"29"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<int> g(n), s(m);\n    for (int i = 0; i < n; i++) cin >> g[i];\n    for (int j = 0; j < m; j++) cin >> s[j];\n    int vui = 0;\n    // sắp xếp cả hai; bánh nhỏ nhất dùng được thì cho em dễ tính nhất\n    cout << vui << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" "+n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%1000+1).join(" ")+"\n"+Array.from({length:n},(_,i)=>(i*104729)%1000+1).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>80*n*Math.log2(n)+200,why:"Với mỗi em, duyệt mọi bánh để tìm bánh vừa nhỏ nhất tốn O(n·m)."},py:{start:"n, m = map(int, input().split())\ng = list(map(int, input().split()))\ns = list(map(int, input().split()))\nvui = 0\n# sắp xếp cả hai; bánh nhỏ nhất dùng được thì cho em dễ tính nhất\nprint(vui)",hints:["Em dễ tính nhất (g nhỏ nhất) nên nhận chiếc bánh nhỏ nhất còn làm em vui: dùng bánh to hơn là phí.","Sắp xếp cả hai, duyệt bánh từ nhỏ đến lớn với một con trỏ vào em dễ tính nhất chưa có bánh.","Bánh nhỏ hơn g của em đó thì cũng nhỏ hơn g của mọi em còn lại: bỏ qua."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] nm = Console.ReadLine().Split();\n        int[] g = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int[] s = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int vui = 0;\n        // sắp xếp cả hai; bánh nhỏ nhất dùng được thì cho em dễ tính nhất\n        Console.WriteLine(vui);\n    }\n}",hints:["Em dễ tính nhất (g nhỏ nhất) nên nhận chiếc bánh nhỏ nhất còn làm em vui: dùng bánh to hơn là phí.","Sắp xếp cả hai, duyệt bánh từ nhỏ đến lớn với một con trỏ vào em dễ tính nhất chưa có bánh.","Bánh nhỏ hơn g của em đó thì cũng nhỏ hơn g của mọi em còn lại: bỏ qua."]}},{t:"Nhảy xa",d:"Có n ô xếp hàng, đánh số 0 … n − 1. Từ ô i được nhảy tới bất kỳ ô nào trong i + 1 … i + aᵢ. Đầu vào: n (1 ≤ n ≤ 10^5) và n số aᵢ (1 ≤ aᵢ ≤ 10^5). Đầu ra: số lần nhảy ít nhất để đi từ ô 0 tới ô n − 1.",tests:[{in:"8\n2 3 1 1 4 2 1 1",out:"3"},{in:"1\n5",out:"0"},{in:"4\n1 1 1 1",out:"3"},{in:"4\n10 1 1 1",out:"1"},{in:"7\n1 4 1 1 1 1 1",out:"3"},{in:"60\n1 3 5 2 4 1 3 5 2 4 1 3 5 2 4 1 3 5 2 4 1 3 5 2 4 1 3 5 2 4 1 3 5 2 4 1 3 5 2 4 1 3 5 2 4 1 3 5 2 4 1 3 5 2 4 1 3 5 2 4",out:"14"}],start:"#include <iostream>\nusing namespace std;\n\nint a[100005];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int buoc = 0, bien = 0, xa = 0;\n    // bien: ô xa nhất tới được bằng buoc bước; xa: xa nhất tới được bằng buoc + 1 bước\n    cout << buoc << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>1+(i*7)%5).join(" "),ns:[500,1000,2000,4000],need:"n",limit:n=>40*n+200,why:"Quy hoạch động “ít bước nhất tới ô i” xét mọi ô trước i tốn O(n²). Cách tham lam theo tầng chỉ một lượt O(n)."},py:{start:"n = int(input())\na = list(map(int, input().split()))\nbuoc = bien = xa = 0\n# bien: ô xa nhất tới được bằng buoc bước; xa: xa nhất tới được bằng buoc + 1 bước\nprint(buoc)",hints:["Chia các ô thành từng “tầng”: tầng k là các ô tới được bằng đúng k bước mà không ít hơn.","Duyệt i từ trái sang: xa = max(xa, i + a[i]). Khi i chạm biên của tầng hiện tại, buộc phải nhảy thêm: buoc += 1, biên mới là xa.","Chỉ duyệt tới n − 2. n = 1 thì đáp án 0."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int buoc = 0, bien = 0, xa = 0;\n        // bien: ô xa nhất tới được bằng buoc bước; xa: xa nhất tới được bằng buoc + 1 bước\n        Console.WriteLine(buoc);\n    }\n}",hints:["Chia các ô thành từng “tầng”: tầng k là các ô tới được bằng đúng k bước mà không ít hơn.","Duyệt i từ trái sang: xa = Math.Max(xa, i + a[i]). Khi i chạm biên của tầng hiện tại, buộc phải nhảy thêm: buoc++, biên mới là xa.","Chỉ duyệt tới n − 2. n = 1 thì đáp án 0."]}}]);

